// v10.497 (D272 · docs/635) 소개뱅크 바깥 감시 — 대상마다 한 번 부르고 결과를 모읍니다(판단은 소개뱅크 서버 · 전달은 n8n).
// 대상 주소는 아래 TARGETS 만 고칩니다. 운영 화면(ADMIN)은 허용 IP 밖이면 403 이 정상이라 403 도 「응답함」으로 봅니다(decisions/automation-server-n8n 미정 #4).
const TARGETS = [
  { target: 'SITE',  url: 'https://sogaebank.com/',                    okStatus: [200] },
  { target: 'API',   url: 'https://sogaebank.com/api/v1/site/status',  okStatus: [200], json: true },
  { target: 'ADMIN', url: 'https://admin.sogaebank.com/',              okStatus: [200, 403] },
];
const out = [];
for (const t of TARGETS) {
  const t0 = Date.now();
  let status = 0, ok = false, note = '';
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: t.url, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 10000, json: !!t.json });
    status = r.statusCode;
    ok = t.okStatus.includes(status);
    if (ok && t.json && r.body && r.body.db === false) { ok = false; note = 'db=false'; }
  } catch (e) { note = String((e && (e.code || e.message)) || 'error').slice(0, 80); }
  out.push({ target: t.target, ok, status, ms: Date.now() - t0, ...(note ? { note } : {}) });
}
return [{ json: { checks: out, fails: out.filter((c) => !c.ok).map((c) => c.target), at: new Date().toISOString() } }];

// 보내기 결과로 텔레그램을 보낼지 정합니다 — 서버에 닿으면 서버가 긴급 알림(UPTIME_DOWN)을 보내므로 n8n 은 「서버에 못 닿을 때」만 알립니다.
// 같은 상태가 이어지면 다시 보내지 않습니다(이 워크플로의 저장 값 · 내려감 → 올라옴 때 한 번씩).
const st = $getWorkflowStaticData('global');
const rep = $input.first().json;
const checks = $('Check targets').first().json;
const reached = Number(rep.statusCode || 0) === 200;
const msgs = [];
if (!reached && !st.down) {
  st.down = true; st.since = checks.at;
  msgs.push(`[소개뱅크] 서버 응답 없음 — 상태 보고를 보내지 못했습니다(응답 ${rep.statusCode || '없음'}). 실패 대상: ${checks.fails.join(', ') || '보고 주소'} · ${checks.at}`);
} else if (reached && st.down) {
  msgs.push(`[소개뱅크] 서버 다시 응답함 — ${st.since} 부터 ${checks.at} 까지. 운영 화면 › 위험감지 › 가동 · 장애 공지에서 공지를 끝냄으로 바꾸십시오.`);
  st.down = false; st.since = null;
}
return msgs.map((text) => ({ json: { text } }));
